    fn render_position_action_icon(
        &self,
        icon: PositionActionIcon,
        enabled: bool,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let color = if enabled {
            cx.theme().foreground
        } else {
            cx.theme().muted_foreground
        };
        canvas(
            |_, _, _| {},
            move |bounds, _, window, _| {
                let x = bounds.origin.x;
                let y = bounds.origin.y;
                let p = |x_offset: f32, y_offset: f32| point(x + px(x_offset), y + px(y_offset));
                let mut path = gpui::PathBuilder::stroke(px(1.25));
                match icon {
                    PositionActionIcon::AlignLeft
                    | PositionActionIcon::AlignHorizontalCenter
                    | PositionActionIcon::AlignRight => {
                        let anchor_x = match icon {
                            PositionActionIcon::AlignLeft => 2.,
                            PositionActionIcon::AlignHorizontalCenter => 8.,
                            PositionActionIcon::AlignRight => 14.,
                            _ => unreachable!(),
                        };
                        path.move_to(p(anchor_x, 1.5));
                        path.line_to(p(anchor_x, 14.5));
                        for (line_y, width) in [(4., 10.), (8., 7.), (12., 11.)] {
                            let start_x = match icon {
                                PositionActionIcon::AlignLeft => anchor_x + 2.,
                                PositionActionIcon::AlignHorizontalCenter => anchor_x - width / 2.,
                                PositionActionIcon::AlignRight => anchor_x - width - 2.,
                                _ => unreachable!(),
                            };
                            path.move_to(p(start_x, line_y));
                            path.line_to(p(start_x + width, line_y));
                        }
                    }
                    PositionActionIcon::AlignTop
                    | PositionActionIcon::AlignVerticalCenter
                    | PositionActionIcon::AlignBottom => {
                        let anchor_y = match icon {
                            PositionActionIcon::AlignTop => 2.,
                            PositionActionIcon::AlignVerticalCenter => 8.,
                            PositionActionIcon::AlignBottom => 14.,
                            _ => unreachable!(),
                        };
                        path.move_to(p(1.5, anchor_y));
                        path.line_to(p(14.5, anchor_y));
                        for (line_x, height) in [(4., 10.), (8., 7.), (12., 11.)] {
                            let start_y = match icon {
                                PositionActionIcon::AlignTop => anchor_y + 2.,
                                PositionActionIcon::AlignVerticalCenter => anchor_y - height / 2.,
                                PositionActionIcon::AlignBottom => anchor_y - height - 2.,
                                _ => unreachable!(),
                            };
                            path.move_to(p(line_x, start_y));
                            path.line_to(p(line_x, start_y + height));
                        }
                    }
                    PositionActionIcon::RotateClockwise90 => {
                        path.add_polygon(&[p(3., 9.), p(8., 4.), p(13., 9.), p(8., 14.)], true);
                        path.move_to(p(3., 5.));
                        path.cubic_bezier_to(p(12., 3.), p(5., 1.), p(10., 1.));
                        path.move_to(p(10., 1.));
                        path.line_to(p(8., 3.));
                        path.move_to(p(10., 1.));
                        path.line_to(p(12., 3.));
                    }
                    PositionActionIcon::FlipHorizontal => {
                        path.move_to(p(8., 1.5));
                        path.line_to(p(8., 14.5));
                        path.add_polygon(&[p(2., 4.), p(6.5, 8.), p(2., 12.)], true);
                        path.add_polygon(&[p(14., 4.), p(9.5, 8.), p(14., 12.)], true);
                    }
                    PositionActionIcon::FlipVertical => {
                        path.move_to(p(1.5, 8.));
                        path.line_to(p(14.5, 8.));
                        path.add_polygon(&[p(4., 2.), p(8., 6.5), p(12., 2.)], true);
                        path.add_polygon(&[p(4., 14.), p(8., 9.5), p(12., 14.)], true);
                    }
                    PositionActionIcon::LockAspectRatio => {
                        path.add_polygon(&[p(2., 2.), p(14., 2.), p(14., 14.), p(2., 14.)], true);
                        path.move_to(p(7., 5.));
                        path.line_to(p(5., 5.));
                        path.line_to(p(5., 7.));
                        path.move_to(p(9., 11.));
                        path.line_to(p(11., 11.));
                        path.line_to(p(11., 9.));
                    }
                }
                if let Ok(path) = path.build() {
                    window.paint_path(path, color);
                }
            },
        )
        .size(px(16.))
        .into_any_element()
    }

